      { q: "कवि के अनुसार कविता और बच्चे का रिश्ता किस बात में है?", options: ["दोनों रोते हैं", "दोनों के खेल और सपनों की कोई सीमा नहीं", "दोनों शांत होते हैं", "दोनों नियमों से बँधे होते हैं"], answer: 1, explain: "कविता शब्दों का खेल है और बच्चे के खेल की तरह उसकी भी सीमा नहीं।", level: 1 },
      { q: "'बिना मुरझाए महकने के माने फूल क्या जाने' से कवि क्या कहना चाहता है?", options: ["फूल जल्दी मुरझाते हैं", "कविता का सौंदर्य कभी नष्ट नहीं होता, जबकि फूल की एक सीमा है", "फूल सुगंध नहीं देता", "कविता में फूल नहीं होते"], answer: 1, explain: "फूल का खिलना और महकना सीमित है, पर कविता का सौंदर्य कालजयी है।", level: 2 },
      { q: "'सब घर एक कर देने के माने बच्चा ही जाने' में 'घर एक कर देने' का आशय क्या है?", options: ["सारे घरों को तोड़ देना", "भेदभाव और सीमाएँ मिटाकर सबको जोड़ देना", "घर बदल लेना", "एक ही घर में बंद हो जाना"], answer: 1, explain: "बच्चे खेल में अपने-पराए का भेद भूल जाते हैं; कविता भी सीमाओं को तोड़कर जोड़ती है।", level: 2 },
      { q: "'बात की चूड़ी मर जाना' का भावार्थ क्या है?", options: ["बात का और स्पष्ट हो जाना", "ज़ोर-ज़बरदस्ती से बात का प्रभावहीन हो जाना", "बात का सबके सामने आ जाना", "बात का तुरंत समझ में आना"], answer: 1, explain: "अधिक कसने से पेंच की चूड़ी घिस जाती है; वैसे ही बात बेअसर हो जाती है।", level: 2 },
      {
        q: "अभिकथन (A): 'बात सीधी थी पर' में कवि अंत में बात को कील की तरह ठोंक देता है, फिर भी बात निष्प्राण रह जाती है।\nकारण (R): भाषा को तोड़ने-मरोड़ने और बनावटी करतब दिखाने से कथ्य कमज़ोर हो जाता है।",
        options: ["A और R दोनों सही हैं, और R, A की सही व्याख्या है।", "A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है।", "A सही है, किंतु R गलत है।", "A गलत है, किंतु R सही है।"],
        answer: 0, explain: "कवि ने भाषा को बनावटी ढंग से घुमाया तो बात कसावरहित हो गई; यही अंत में निष्प्राण रहने का कारण है।", level: 2, keepOrder: true
      },
      { q: "'कविता के बहाने' में चिड़िया, फूल और बच्चे का क्रम किस बात का संकेत देता है?", options: ["सीमा से असीम की ओर बढ़ना", "बड़े से छोटे की ओर आना", "दिन से रात की ओर जाना", "शहर से गाँव की ओर जाना"], answer: 0, explain: "चिड़िया की उड़ान और फूल का खिलना सीमित हैं, जबकि बच्चे के खेल की कोई सीमा नहीं; कविता इसी असीम खेल जैसी है।", level: 2 },
      { q: "एक कवि अपनी कविता में अत्यंत कठिन और अलंकृत शब्द भर देता है, पर पाठक उसे समझ नहीं पाते। 'बात सीधी थी पर' के आधार पर उसे क्या सीख मिलेगी?", options: ["और कठिन शब्द प्रयोग करे", "भाषा को सहज रखकर सही बात का सही शब्द से मेल बैठाए", "कविता लिखना छोड़ दे", "केवल तुक पर ध्यान दे"], answer: 1, explain: "कविता का सार है कि बनावट की जगह सहज, सटीक भाषा ही प्रभावी होती है।", level: 3 },
      {
        q: "अभिकथन (A): 'कविता के बहाने' में कविता को बच्चों के खेल जैसा कहा गया है।\nकारण (R): खेल में अतीत, वर्तमान और भविष्य सब उपकरण बन सकते हैं और रचनात्मक ऊर्जा सीमाओं को तोड़ देती है।",
        options: ["A और R दोनों सही हैं, और R, A की सही व्याख्या है।", "A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है।", "A सही है, किंतु R गलत है।", "A गलत है, किंतु R सही है।"],
        answer: 0, explain: "कविता शब्दों का खेल है जिसमें जड़-चेतन, अतीत-वर्तमान-भविष्य सब उपकरण हैं और सीमाएँ टूट जाती हैं।", level: 3, keepOrder: true
      },
      { q: "'बात ने शरारती बच्चे की तरह पूछा – क्या तुमने भाषा को सहूलियत से बरतना कभी नहीं सीखा?' इसमें बात को शरारती बच्चे के रूप में दिखाने का क्या प्रभाव है?", options: ["बात बहुत छोटी लगने लगती है", "कवि की भूल पर हल्का व्यंग्य और सीख सहजता से उभरती है", "बात क्रोधित प्रतीत होती है", "कविता का विषय बदल जाता है"], answer: 1, explain: "मानवीकरण से बात कवि पर हल्का व्यंग्य करती है और सहज भाषा की सीख विनोदपूर्ण ढंग से मिलती है।", level: 3 },
      { q: "'कविता के बहाने' कविता यांत्रिक युग में कविता के किस प्रश्न का उत्तर देती है?", options: ["कविता का भविष्य और उसके अस्तित्व की संभावना", "कविता का मूल्य कितना है", "कविता किस भाषा में लिखी जाए", "कविता का प्रकाशन कैसे हो"], answer: 0, explain: "यांत्रिकता के दबाव में कविता के अस्तित्व पर आशंका है; कविता अपनी असीम संभावनाओं से इसका उत्तर देती है।", level: 3 }
